from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.spy = self.AddEquity("SPY", Resolution.Minute).Symbol
        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.spy_exit_ticket = None
        self.held_symbol = None
        self.held_expiry = None
        self.entry_fill_price = None
        self.pending_entry_time = None
        self.expiration_block_date = None

        # Profit target expressed as a 20% gain from the actual entry fill price.
        self.profit_target = 0.20

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        self.previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        self.previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        bar_time = bar.EndTime.time()
        if bullish_cross and time(9, 45) <= bar_time <= time(14, 30):
            self.pending_entry_time = bar.EndTime

    def OnData(self, data):
        self.HandleUnexpectedSpyHolding()
        self.HandleExpirationSafety()

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            self.HandleTimeStop()
            self.HandleProfitTarget(data)

        # A signal is consumed only on the Slice corresponding to its bar close.
        if self.pending_entry_time is not None:
            signal_time = self.pending_entry_time
            self.pending_entry_time = None

            if signal_time == self.Time:
                self.TryEnter(data)

    def TryEnter(self, data):
        if self.expiration_block_date == self.Time.date():
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity != 0:
            return

        if self.IsOpen(self.entry_ticket):
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug(f"{self.Time}: Entry skipped - no SPY option chain.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped - invalid SPY price.")
            return

        today = self.Time.date()
        eligible_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if (contract.Expiry.date() - today).days >= 7
            }
        )

        if not eligible_expirations:
            self.Debug(f"{self.Time}: Entry skipped - no expiration at least 7 calendar days away.")
            return

        expiry = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(f"{self.Time}: Entry skipped - no qualifying call for {expiry}.")
            return

        selected = min(candidates, key=lambda c: (c.Strike, str(c.Symbol)))

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"{self.Time}: Entry submitted - {selected.Symbol} "
            f"expiry {expiry}, strike {selected.Strike}."
        )

    def HandleProfitTarget(self, data):
        if self.entry_fill_price is None or self.IsOpen(self.exit_ticket):
            return

        contract = self.GetHeldContractFromSlice(data)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * (1 + self.profit_target):
            self.SubmitExit("profit target")
            self.Debug(f"{self.Time}: Exit submitted - profit target reached.")

    def HandleTimeStop(self):
        if self.held_expiry is None or self.IsOpen(self.exit_ticket):
            return

        previous_trading_day = self.GetPreviousTradingDay(self.held_expiry)
        if (
            self.Time.date() == previous_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("pre-expiration time stop")
            self.Debug(f"{self.Time}: Exit submitted - pre-expiration time stop.")

    def HandleExpirationSafety(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        if self.Time.date() >= self.held_expiry:
            self.expiration_block_date = self.Time.date()

            quantity = self.Portfolio[self.held_symbol].Quantity
            if quantity != 0 and not self.IsOpen(self.exit_ticket):
                self.SubmitExit("expiration safety")
                self.Debug(
                    f"{self.Time}: Exit submitted - expiration safety for {self.held_symbol}."
                )

    def HandleUnexpectedSpyHolding(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.IsOpen(self.spy_exit_ticket):
            return

        self.Debug(f"{self.Time}: Unexpected SPY exercise/assignment holding; liquidating.")
        self.spy_exit_ticket = self.MarketOrder(self.spy, -quantity)

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        if self.IsOpen(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity, tag=reason)

    def GetHeldContractFromSlice(self, data):
        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == self.held_symbol:
                    return contract
        return None

    def GetPreviousTradingDay(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min), False
        ):
            candidate -= timedelta(days=1)

        return candidate

    def IsOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.held_expiry = order_event.Symbol.ID.Date.date()
                self.entry_fill_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled - {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"{self.Time}: Entry order did not complete - {order_event.Status}.")

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"{self.Time}: Exit filled - {order_event.Symbol} "
                    f"at {order_event.FillPrice}."
                )
                if self.Portfolio[order_event.Symbol].Quantity == 0:
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_fill_price = None

