from AlgorithmImports import *
from datetime import datetime, timedelta, time


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    PROFIT_TARGET_MULTIPLIER = 1.50

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(-100, 100, timedelta(days=0), timedelta(days=365))
        self.option_symbol = option.Symbol

        self.close_window = RollingWindow[float](20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_signal = False

        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.expiration_block_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        if self.close_window.IsReady:
            prior_fast = sum(self.close_window[i] for i in range(5)) / 5.0
            prior_slow = sum(self.close_window[i] for i in range(20)) / 20.0
        else:
            prior_fast = None
            prior_slow = None

        self.close_window.Add(float(bar.Close))

        if not self.close_window.IsReady or prior_fast is None:
            if self.close_window.IsReady:
                self.previous_fast = sum(self.close_window[i] for i in range(5)) / 5.0
                self.previous_slow = sum(self.close_window[i] for i in range(20)) / 20.0
            return

        current_fast = sum(self.close_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.close_window[i] for i in range(20)) / 20.0

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)
        bullish_cross = prior_fast <= prior_slow and current_fast > current_slow

        if eligible_time and bullish_cross:
            self.pending_entry_signal = True

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProcessing()
        self.HandleTimeStop()
        self.HandleProfitTarget(slice)

        if self.pending_entry_signal:
            self.pending_entry_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.held_contract is not None:
            return

        if self.entry_order_id is not None and self.IsOrderOpen(self.entry_order_id):
            return

        if self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id):
            return

        if self.expiration_block_date == self.Time.date():
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: SPY price unavailable.")
            return

        try:
            chain = slice.OptionChains[self.option_symbol]
        except (KeyError, TypeError):
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        qualifying_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if (contract.Expiry.date() - today).days >= 7
        })

        if not qualifying_expiries:
            self.Debug("Skipped entry: no expiration at least seven calendar days away.")
            return

        expiration = qualifying_expiries[0]
        spy_price = float(slice.Bars[self.spy].Close)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected = min(candidates, key=lambda c: (float(c.Strike), str(c.Symbol)))
        ticket = self.MarketOrder(selected.Symbol, 1)

        self.entry_order_id = ticket.OrderId
        self.entry_fill_price = None
        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {expiration} strike {selected.Strike}."
        )

    def HandleProfitTarget(self, slice):
        if self.held_contract is None or self.entry_fill_price is None:
            return

        if self.exit_order_id is not None and self.IsOrderOpen(self.exit_order_id):
            return

        contract = self.GetContractFromSlice(slice, self.held_contract)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_fill_price * self.PROFIT_TARGET_MULTIPLIER:
            self.SubmitExit("profit target")

    def HandleTimeStop(self):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        previous_trading_day = self.GetPreviousTradingDay(expiry)

        if self.Time.date() == previous_trading_day and self.Time.time() == time(15, 45):
            self.SubmitExit("pre-expiration time stop")

    def HandleExpirationProcessing(self):
        if self.held_contract is None:
            return

        expiry = self.held_contract.ID.Date.date()
        if self.Time.date() >= expiry:
            self.expiration_block_date = self.Time.date()
            if self.exit_order_id is None or not self.IsOrderOpen(self.exit_order_id):
                self.SubmitExit("expiration processing")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY exercise/assignment position detected; liquidating.")
            self.Liquidate(self.spy)

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            self.Transactions.CancelOrder(order.Id, "Replacing open exit order.")

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug(f"Exit submitted ({reason}): {self.held_contract}.")

    def OnOrderEvent(self, order_event):
        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_contract = order_event.Symbol
                self.entry_fill_price = float(order_event.FillPrice)
                self.entry_order_id = None
                self.Debug(
                    f"Entry filled: {order_event.Symbol} at {order_event.FillPrice}."
                )
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.entry_order_id = None
                self.Debug(f"Entry order closed without fill: {order_event.Symbol}.")

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol} at {order_event.FillPrice}."
                )
                self.held_contract = None
                self.entry_fill_price = None
                self.exit_order_id = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_order_id = None

    def GetContractFromSlice(self, slice, symbol):
        try:
            chain = slice.OptionChains[self.option_symbol]
        except (KeyError, TypeError):
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract
        return None

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(candidate, False):
            candidate -= timedelta(days=1)

        return candidate

    def IsOrderOpen(self, order_id):
        if order_id is None:
            return False

        order = self.Transactions.GetOrderById(order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

