        self.exit_order_id = ticket.OrderId
        self.Debug(f"{self.Time} Exit submitted: {self.held_option}; {reason}")

    def HasOpenEntryOrder(self):
        if self.entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.entry_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def HasOpenExitOrder(self):
        if self.exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self.exit_order_id)
        return order is not None and order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def CancelOpenExitOrder(self):
        if self.HasOpenExitOrder():
            self.Transactions.CancelOrder(self.exit_order_id, "Replacing exit order")

    def GetOptionMidpoint(self, data, symbol):
        quote_bar = data.QuoteBars.get(symbol)
        if quote_bar is None or quote_bar.Bid is None or quote_bar.Ask is None:
            return None

        bid = float(quote_bar.Bid.Close)
        ask = float(quote_bar.Ask.Close)
        if bid <= 0 or ask <= 0:
            return None

        return (bid + ask) / 2.0

    def IsPreviousOptionTradingDay(self):
        if self.expiry_date is None:
            return False

        candidate = self.expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsOpen(
            datetime.combine(candidate, time(12, 0)),
            False
        ):
            candidate -= timedelta(days=1)

        return self.Time.date() == candidate

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if len(self.Transactions.GetOpenOrders(self.spy)) == 0:
            self.Debug(f"{self.Time} Unexpected SPY exercise/assignment position; liquidating.")
            self.MarketOrder(self.spy, -quantity, tag="Unexpected exercise/assignment cleanup")

