            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.Debug(f"Exit order closed without fill: {order_event.Message}.")
                self.exit_ticket = None

    @staticmethod
    def _ticket_is_open(ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

