        if self.Portfolio[self.held_option].Quantity == 0:
            return

        if self.exit_order_id is not None:
            return

        if self.entry_fill_price is None:
            return

        if data.QuoteBars.ContainsKey(self.held_option):
            quote = data.QuoteBars[self.held_option]
            if quote.Bid is not None and quote.Ask is not None:
                bid = quote.Bid.Close
                ask = quote.Ask.Close
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= self.entry_fill_price * (1.0 + self.PROFIT_TARGET_PCT):
