        self.Securities[self.spy].SetDataNormalizationMode(DataNormalizationMode.Raw)

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(0), timedelta(days=365))
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_entry_bar_end = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

        self.held_contract = None
        self.held_expiry = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.block_entries_date = None
        self.spy_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(IndicatorDataPoint(bar.EndTime, bar.Close))
        self.slow.Update(IndicatorDataPoint(bar.EndTime, bar.Close))

        bullish_cross = (
            self.fast.IsReady
            and self.slow.IsReady
            and self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

        bar_time = bar.EndTime.time()
        if bullish_cross and bar_time >= time(9, 45) and bar_time <= time(14, 30):
            self.pending_entry_bar_end = bar.EndTime

    def OnData(self, slice):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpiration()

        if self.held_contract is not None and self.OptionQuantity() > 0:
            self.HandlePositionExit(slice)

        if self.pending_entry_bar_end is not None:
            pending_end = self.pending_entry_bar_end
            self.pending_entry_bar_end = None

            if pending_end == self.Time:
                self.TryEnter(slice)

    def TryEnter(self, slice):
        if self.block_entries_date == self.Time.date():
            return

        if self.held_contract is not None or self.OptionQuantity() != 0:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        if not slice.OptionChains.ContainsKey(self.option_symbol):
            self.Debug(f"{self.Time}: Entry skipped: no SPY option chain in Slice.")
            return

        spy_price = self.Securities[self.spy].Price
        if spy_price <= 0:
            self.Debug(f"{self.Time}: Entry skipped: invalid SPY price.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = self.Time.date() + timedelta(days=7)

        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug(f"{self.Time}: Entry skipped: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain.Contracts.Values
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                f"{self.Time}: Entry skipped: no qualifying call for {selected_expiry}."
            )
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.held_contract = selected.Symbol
        self.held_expiry = selected.Expiry.date()
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"{self.Time}: Entry submitted: {selected.Symbol}, "
            f"expiry {self.held_expiry}, strike {selected.Strike}."
        )

    def HandlePositionExit(self, slice):
        if self.IsOrderOpen(self.exit_ticket):
            return

        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(
            self.held_expiry
        )

        if self.Time.date() == previous_trading_day.date() and self.Time.time() == time(15, 45):
            self.SubmitExit("expiration time stop")
            return

        if self.entry_price is None:
            return

        if not slice.QuoteBars.ContainsKey(self.held_contract):
            return

        quote = slice.QuoteBars[self.held_contract]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.20:
            self.SubmitExit("profit target")

    def HandleExpiration(self):
        if self.held_contract is None or self.OptionQuantity() <= 0:
            return

        if self.Time.date() >= self.held_expiry:
            self.block_entries_date = self.Time.date()
            if not self.IsOrderOpen(self.exit_ticket):
                self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        quantity = self.OptionQuantity()
        if quantity <= 0 or self.IsOrderOpen(self.exit_ticket):
            return

        for order in self.Transactions.GetOpenOrders(self.held_contract):
            if order.Quantity < 0:
                self.Transactions.CancelOrder(order.Id, f"Replacing exit: {reason}")

        self.exit_ticket = self.MarketOrder(self.held_contract, -quantity)
        self.Debug(f"{self.Time}: Exit submitted for {self.held_contract}: {reason}.")

    def HandleUnexpectedSpyPosition(self):
        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0 or self.IsOrderOpen(self.spy_liquidation_ticket):
            return

        self.Debug(
            f"{self.Time}: Unexpected SPY exercise/assignment position ({quantity}); liquidating."
        )
        self.spy_liquidation_ticket = self.MarketOrder(self.spy, -quantity)

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"{self.Time}: Entry filled: {self.held_contract} at {self.entry_price}."
                )

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"{self.Time}: Exit filled: {order_event.Symbol}.")
                if self.OptionQuantity() == 0:
                    self.held_contract = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.entry_ticket = None
                    self.exit_ticket = None

        self.HandleUnexpectedSpyPosition()

    def OptionQuantity(self):
        if self.held_contract is None:
            return 0
        return self.Portfolio[self.held_contract].Quantity

    def IsOrderOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

