        self._five_minute_closes = deque(maxlen=21)
        self._bar_bucket_end = None
        self._minute_bars = {}

        self._held_symbol = None
        self._held_expiry = None
        self._entry_price = None
        self._entry_order_id = None
        self._pending_symbol = None
        self._exit_order_id = None
        self._time_stop_date = None
        self._no_entry_date = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        if self.Portfolio[self.spy].Invested:
            self.Debug("Unexpected SPY exercise/assignment position; liquidating.")
            self.Liquidate(self.spy)

        self._process_expiration_guard(today)
        self._process_exits(data, today)
        self._update_five_minute_bars(data, today)

    def _update_five_minute_bars(self, data, today):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        end_time = minute_bar.EndTime
        clock = end_time.time()

        if clock <= time(9, 30) or clock > time(16, 0):
            return

        minute = end_time.minute
        if minute % 5 == 0:
            bucket_end = end_time
        else:
            bucket_end = end_time + timedelta(minutes=5 - (minute % 5))

        if self._bar_bucket_end is not None and bucket_end != self._bar_bucket_end:
            self._bar_bucket_end = None
            self._minute_bars = {}

        if self._bar_bucket_end is None:
            self._bar_bucket_end = bucket_end
            self._minute_bars = {}

        self._minute_bars[end_time] = minute_bar

        if end_time != bucket_end:
            return

        expected_times = {
            bucket_end - timedelta(minutes=offset)
            for offset in range(5)
        }

        if set(self._minute_bars.keys()) == expected_times:
            ordered = [self._minute_bars[t] for t in sorted(expected_times)]
            close = ordered[-1].Close
            self._on_completed_five_minute_bar(bucket_end, close, data, today)

        self._bar_bucket_end = None
        self._minute_bars = {}

    def _on_completed_five_minute_bar(self, bar_end, close, data, today):
        self._five_minute_closes.append(close)

        if len(self._five_minute_closes) < 21:
            return

        closes = list(self._five_minute_closes)
        previous = closes[:-1]
        current = closes[1:]

        previous_fast = sum(previous[-5:]) / 5.0
        previous_slow = sum(previous[-20:]) / 20.0
        current_fast = sum(current[-5:]) / 5.0
        current_slow = sum(current[-20:]) / 20.0

        bullish_cross = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        clock = bar_end.time()
        eligible_time = time(9, 45) <= clock <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(data, today)

    def _try_enter(self, data, today):
        if self._no_entry_date == today:
            return

        if self._held_symbol is not None or self._entry_order_id is not None:
            return

        if self._exit_order_id is not None:
            return

        if self.spy not in data.Bars:
            self.Debug("Entry skipped: SPY price unavailable.")
            return

        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Entry skipped: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)
        eligible_expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expiries:
            self.Debug("Entry skipped: no eligible expiration.")
            return

        expiry = eligible_expiries[0]
        spy_price = data.Bars[self.spy].Close
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no eligible call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._pending_symbol = selected.Symbol
        ticket = self.MarketOrder(selected.Symbol, 1)
        self._entry_order_id = ticket.OrderId
        self.Debug(
            f"Entry submitted: {selected.Symbol} exp {expiry} strike {selected.Strike}"
        )

    def _process_exits(self, data, today):
        if self._held_symbol is None:
            return

        if not self.Portfolio[self._held_symbol].Invested:
            self._clear_position_state()
            return

        if self._time_stop_date == today:
            if self.Time.time() >= time(15, 45):
                self._submit_exit("Time-stop exit")
            return

        if self._entry_price is None or self._exit_order_id is not None:
            return

        quote = data.QuoteBars.get(self._held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self._entry_price * (1.0 + self.profit_target):
            self._cancel_open_exit()
            self._submit_exit("Profit-target exit")

    def _process_expiration_guard(self, today):
        if self._held_symbol is None or self._held_expiry is None:
            return

        if today >= self._held_expiry:
            self._no_entry_date = today
            self._submit_exit("Expiration safety exit")

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_order_id is not None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity == 0:
            self._clear_position_state()
            return

        ticket = self.MarketOrder(self._held_symbol, -quantity)
        self._exit_order_id = ticket.OrderId
        self.Debug(f"{reason}: {self._held_symbol}")

    def _cancel_open_exit(self):
        if self._exit_order_id is None:
            return

        ticket = self.Transactions.GetOrderTicket(self._exit_order_id)
        if ticket is not None:
            ticket.Cancel()

    def OnOrderEvent(self, order_event):
        if (
            order_event.Symbol == self.spy and
            self.Portfolio[self.spy].Invested
        ):
            self.Debug("Unexpected SPY exercise/assignment order event; liquidating.")
            self.Liquidate(self.spy)

        if order_event.OrderId == self._entry_order_id:
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self._held_symbol = self._pending_symbol
                self._held_expiry = self._held_symbol.ID.Date.date()
                self._entry_price = order_event.FillPrice
                self._time_stop_date = self.Securities[
                    self.spy
                ].Exchange.Hours.GetPreviousTradingDay(
                    self._held_expiry
                ).date()
                self.Debug(
                    f"Entry filled: {self._held_symbol} @ {self._entry_price}"
                )
                self._entry_order_id = None
                self._pending_symbol = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order canceled or rejected.")
                self._entry_order_id = None
                self._pending_symbol = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                self._clear_position_state()
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._exit_order_id = None

    def _clear_position_state(self):
        self._held_symbol = None
        self._held_expiry = None
        self._entry_price = None
        self._entry_order_id = None
        self._pending_symbol = None
        self._exit_order_id = None
        self._time_stop_date = None

