from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class FiveMinuteSpyCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetTimeZone(TimeZones.NewYork)
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)

        self.profit_target = float(self.GetParameter("profit_target") or "0.20")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(lambda universe: universe.IncludeWeeklys().Strikes(-100, 100).Expiration(0, 365))
        self.option_symbol = option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.pending_entry = False
        self.held_contract = None
        self.entry_order_id = None
        self.exit_order_id = None
        self.entry_fill_price = None
        self.no_entry_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime
        if end_time.hour < 9 or (end_time.hour == 9 and end_time.minute < 35):
            return
        if end_time.hour > 16 or (end_time.hour == 16 and end_time.minute > 0):
            return
        if end_time.minute % 5 != 0:
            return

        self.fast_closes.append(bar.Close)
        self.slow_closes.append(bar.Close)

        if len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / len(self.fast_closes)
        slow = sum(self.slow_closes) / len(self.slow_closes)

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        eligible_time = (
            (end_time.hour == 9 and end_time.minute >= 45)
            or (10 <= end_time.hour <= 13)
            or (end_time.hour == 14 and end_time.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self.pending_entry = True

    def OnData(self, data):
        self.HandleUnexpectedSpyPosition()
        self.HandleExpirationProtection()
        self.HandleOptionExit(data)

        if self.pending_entry:
            self.pending_entry = False
            self.TryEnter(data)

    def TryEnter(self, data):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_contract is not None and self.Portfolio[self.held_contract].Invested:
            return

        if self.entry_order_id is not None:
            order = self.Transactions.GetOrderById(self.entry_order_id)
            if order is not None and order.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return
            self.entry_order_id = None

        spy_bar = data.Bars.get(self.spy)
        chain = data.OptionChains.get(self.option_symbol)

        if spy_bar is None or chain is None:
            self.Debug("Entry skipped: missing SPY bar or option chain.")
            return

        current_date = self.Time.date()
        spy_price = spy_bar.Close
        eligible_expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= current_date + timedelta(days=7)
            }
        )

        if not eligible_expirations:
            self.Debug("Entry skipped: no expiration at least 7 calendar days away.")
            return

        expiration = eligible_expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == expiration
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Entry skipped: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.held_contract = selected.Symbol
        self.entry_fill_price = None
        self.Debug("Entry submitted: {0}".format(selected.Symbol))

    def HandleOptionExit(self, data):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.exit_order_id is not None:
            order = self.Transactions.GetOrderById(self.exit_order_id)
            if order is not None and order.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                return
            self.exit_order_id = None

        contract = self.GetCurrentContract(data, self.held_contract)

        if self.entry_fill_price is not None and contract is not None:
            bid = contract.BidPrice
            ask = contract.AskPrice
            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= self.entry_fill_price * (1.0 + self.profit_target):
                    self.SubmitExit("profit target")
                    return

        expiry = self.held_contract.ID.Date
        previous_trading_day = self.Securities[self.spy].Exchange.Hours.GetPreviousTradingDay(expiry)

        if (
            self.Time.date() == previous_trading_day.date()
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self.SubmitExit("pre-expiration time stop")

    def HandleExpirationProtection(self):
        if self.held_contract is None or not self.Portfolio[self.held_contract].Invested:
            return

        if self.Time.date() >= self.held_contract.ID.Date.date():
            self.no_entry_date = self.Time.date()
            self.SubmitExit("expiration protection")

    def HandleUnexpectedSpyPosition(self):
        if self.Portfolio[self.spy].Invested:
            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(self.spy, -quantity)
                self.Debug("Unexpected SPY exercise/assignment position liquidated.")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.exit_order_id is not None:
            existing = self.Transactions.GetOrderById(self.exit_order_id)
            if existing is not None and existing.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                existing_ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
                if existing_ticket is not None:
                    existing_ticket.Cancel("Replacing exit order.")

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_contract, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({0}): {1}".format(reason, self.held_contract))

    def GetCurrentContract(self, data, symbol):
        chain = data.OptionChains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def OnOrderEvent(self, orderEvent):
